ALTER TABLE public.workspaces ADD COLUMN provider_service_roles text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.workspaces ADD CONSTRAINT provider_service_roles_allowed CHECK (provider_service_roles <@ ARRAY['nemt_business','independent_contractor','medical_delivery_driver']::text[]);
ALTER TABLE public.vehicles ADD COLUMN vin text, ADD COLUMN service_regions text[] NOT NULL DEFAULT '{}', ADD COLUMN service_counties text[] NOT NULL DEFAULT '{}', ADD COLUMN service_cities text[] NOT NULL DEFAULT '{}', ADD COLUMN service_zips text[] NOT NULL DEFAULT '{}', ADD COLUMN travel_radius_miles integer;
ALTER TABLE public.vehicles ADD CONSTRAINT vehicle_radius_safe CHECK (travel_radius_miles BETWEEN 0 AND 500);
ALTER TABLE public.saved_patients ADD COLUMN preferred_driver_id uuid REFERENCES public.drivers(id);
ALTER TABLE public.user_portal_preferences ADD COLUMN history_columns jsonb;
ALTER TABLE public.notifications ADD COLUMN dismissed_at timestamptz;
CREATE FUNCTION public.save_provider_service_roles(_ws uuid,_roles text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF _roles IS NULL OR NOT (_roles <@ ARRAY['nemt_business','independent_contractor','medical_delivery_driver']::text[]) OR NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND w.account_type='provider' AND w.status='active' AND NOT w.is_test_account AND p.status='active') THEN RAISE EXCEPTION 'Authorized provider owner required'; END IF;
UPDATE public.workspaces SET provider_service_roles=_roles WHERE id=_ws;
INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,details) VALUES(_ws,'provider_service_roles_updated',auth.uid(),jsonb_build_object('roles',_roles)); END $$;
REVOKE ALL ON FUNCTION public.save_provider_service_roles(uuid,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_provider_service_roles(uuid,text[]) TO authenticated;
CREATE FUNCTION public.preferred_driver_scope_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.preferred_driver_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.preferred_driver_id IS DISTINCT FROM OLD.preferred_driver_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id) AND NOT EXISTS(SELECT 1 FROM public.drivers d JOIN public.workspaces w ON w.id=d.workspace_id WHERE d.id=NEW.preferred_driver_id AND d.workspace_id=NEW.workspace_id AND w.account_type='provider' AND d.status='active' AND (d.license_expiry IS NULL OR d.license_expiry>=current_date) AND public.business_record_access(d.workspace_id,'drivers',d.id,'read')) THEN RAISE EXCEPTION 'Choose an active eligible driver in this provider workspace';END IF;RETURN NEW;END $$;
CREATE TRIGGER preferred_driver_scope_guard BEFORE INSERT OR UPDATE ON public.saved_patients FOR EACH ROW EXECUTE FUNCTION public.preferred_driver_scope_guard();
CREATE FUNCTION public.patient_driver_suggestion(_patient uuid,_service text DEFAULT 'ambulatory',_date date DEFAULT current_date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.saved_patients; chosen uuid; prior uuid;warning text; BEGIN
SELECT * INTO p FROM public.saved_patients WHERE id=_patient AND active AND kind='patient';
IF p.workspace_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.workspace_id=p.workspace_id AND m.user_id=auth.uid() AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND w.account_type='provider') THEN RAISE EXCEPTION 'Authorized provider patient required';END IF;
SELECT d.id INTO chosen FROM public.drivers d WHERE d.id=p.preferred_driver_id AND d.workspace_id=p.workspace_id AND d.status='active' AND _service=ANY(d.service_capabilities) AND (d.license_expiry IS NULL OR d.license_expiry>=_date) AND NOT (d.vacation_start IS NOT NULL AND d.vacation_end IS NOT NULL AND _date BETWEEN d.vacation_start AND d.vacation_end);
IF p.preferred_driver_id IS NOT NULL AND chosen IS NULL THEN warning:='Preferred driver is unavailable or ineligible. You may choose another driver.'; END IF;
IF chosen IS NULL THEN SELECT t.driver_id INTO prior FROM public.trips t JOIN public.ride_requests r ON r.id=t.ride_request_id WHERE r.saved_patient_id=p.id AND r.workspace_id=p.workspace_id AND t.status='completed' AND t.completed_at IS NOT NULL ORDER BY t.completed_at DESC,t.id DESC LIMIT 1;
SELECT d.id INTO chosen FROM public.drivers d WHERE d.id=prior AND d.workspace_id=p.workspace_id AND d.status='active' AND _service=ANY(d.service_capabilities) AND (d.license_expiry IS NULL OR d.license_expiry>=_date) AND NOT (d.vacation_start IS NOT NULL AND d.vacation_end IS NOT NULL AND _date BETWEEN d.vacation_start AND d.vacation_end); END IF;
RETURN jsonb_build_object('driverId',chosen,'warning',warning,'source',CASE WHEN chosen IS NULL THEN 'unassigned' WHEN chosen=p.preferred_driver_id THEN 'preferred' ELSE 'last_completed' END);END $$;
REVOKE ALL ON FUNCTION public.patient_driver_suggestion(uuid,text,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.patient_driver_suggestion(uuid,text,date) TO authenticated;
CREATE FUNCTION public.provider_active_fleet(_ws uuid,_service text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.drivers d WHERE d.workspace_id=_ws AND d.status='active' AND _service=ANY(d.service_capabilities) AND (d.license_expiry IS NULL OR d.license_expiry>=current_date)) AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=_ws AND v.status='active' AND v.vehicle_category IS NOT NULL AND _service=ANY(v.service_capabilities)) $$;
REVOKE ALL ON FUNCTION public.provider_active_fleet(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.provider_active_fleet(uuid,text) TO authenticated;
CREATE FUNCTION public.provider_fleet_opportunity_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ws uuid;cap text;BEGIN
IF TG_TABLE_NAME='provider_trip_offers' THEN ws:=NEW.provider_workspace_id; SELECT capability INTO cap FROM public.trip_distributions WHERE id=NEW.distribution_id;
ELSIF TG_TABLE_NAME='trip_distributions' THEN IF TG_OP='UPDATE' AND NEW.selected_workspace_id IS NOT DISTINCT FROM OLD.selected_workspace_id THEN RETURN NEW;END IF;ws:=NEW.selected_workspace_id;cap:=NEW.capability;
ELSE IF TG_OP='UPDATE' AND NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to AND NEW.driver_id IS NOT DISTINCT FROM OLD.driver_id AND NEW.vehicle_id IS NOT DISTINCT FROM OLD.vehicle_id AND NEW.network_provider_workspace_id IS NOT DISTINCT FROM OLD.network_provider_workspace_id THEN RETURN NEW;END IF;
IF NEW.trip_kind IS DISTINCT FROM 'passenger' THEN RETURN NEW;END IF;cap:=NEW.transport_type;ws:=coalesce(NEW.contractor_assigned_workspace_id,NEW.network_provider_workspace_id);
IF ws IS NULL AND NEW.assigned_to IS NOT NULL THEN SELECT m.workspace_id INTO ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=NEW.assigned_to AND m.role='owner' AND m.removed_at IS NULL AND w.account_type='provider' ORDER BY w.created_at LIMIT 1;END IF;
IF ws IS NULL AND (NEW.driver_id IS NOT NULL OR NEW.vehicle_id IS NOT NULL) THEN SELECT workspace_id INTO ws FROM public.ride_requests WHERE id=NEW.ride_request_id;END IF;
IF NEW.driver_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.drivers WHERE id=NEW.driver_id AND workspace_id=ws AND status='active' AND cap=ANY(service_capabilities)) THEN RAISE EXCEPTION 'Active eligible driver in the assigned provider workspace required';END IF;
IF NEW.vehicle_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id=NEW.vehicle_id AND workspace_id=ws AND status='active' AND cap=ANY(service_capabilities)) THEN RAISE EXCEPTION 'Active eligible vehicle in the assigned provider workspace required';END IF;
END IF;
IF ws IS NOT NULL AND NOT public.provider_active_fleet(ws,cap) THEN RAISE EXCEPTION 'Add an active eligible driver and vehicle before offering or accepting transportation work';END IF;RETURN NEW;END $$;
CREATE TRIGGER provider_fleet_offer_guard BEFORE INSERT OR UPDATE ON public.provider_trip_offers FOR EACH ROW EXECUTE FUNCTION public.provider_fleet_opportunity_guard();
CREATE TRIGGER provider_fleet_selection_guard BEFORE INSERT OR UPDATE ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.provider_fleet_opportunity_guard();
CREATE TRIGGER provider_fleet_assignment_guard BEFORE INSERT OR UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION public.provider_fleet_opportunity_guard();
CREATE FUNCTION public.accepted_connection_notices() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ws uuid;other_ws uuid;recipient uuid;other_name text;other_type text;BEGIN
IF NOT NEW.active OR (TG_OP='UPDATE' AND OLD.active) THEN RETURN NEW;END IF;
FOREACH ws IN ARRAY ARRAY[NEW.workspace_a,NEW.workspace_b] LOOP
other_ws:=CASE WHEN ws=NEW.workspace_a THEN NEW.workspace_b ELSE NEW.workspace_a END;
SELECT display_name,account_type INTO other_name,other_type FROM public.workspaces WHERE id=other_ws;
FOR recipient IN SELECT m.user_id FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=ws AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account LOOP
INSERT INTO public.notifications(user_id,type,title,body,link,communication) VALUES(recipient,'accepted_connection','New connection accepted',coalesce(other_name,'Connected account'),'/portal/contacts?tab=connections',jsonb_build_object('dedupeKey','accepted-connection:'||NEW.id||':'||recipient,'state','prepared','channel','in_app','workspaceId',ws,'connectionId',NEW.id,'otherWorkspaceId',other_ws,'accountType',other_type,'relationshipType',NEW.relationship_kind,'acceptedAt',NEW.created_at,'emailTemplate','connection-accepted','emailState','not_configured','deliveryEnabled',false)) ON CONFLICT DO NOTHING;
END LOOP;END LOOP;RETURN NEW;END $$;
CREATE TRIGGER accepted_connection_notices AFTER INSERT OR UPDATE OF active ON public.account_business_connections FOR EACH ROW EXECUTE FUNCTION public.accepted_connection_notices();
COMMENT ON COLUMN public.notifications.dismissed_at IS 'Recipient alert dismissal only; immutable accepted-connection communication evidence and the relationship remain retained. No delivery worker or email outbox is activated.';